@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}

:root { --ax: var(--fl-accent); }
html.fl-dark { --ax: color-mix(in srgb, var(--fl-accent) 62%, #fff); }

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  font-family: "Plus Jakarta Sans", ui-sans-serif, system-ui, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color: var(--fl-text);
  background: radial-gradient(1000px 320px at 12% -100px, color-mix(in srgb, var(--fl-accent) 7%, transparent), transparent) var(--fl-bg);
}

.wrap { max-width: 1120px; margin: 0 auto; padding: 28px 24px 64px; }
.num { font-variant-numeric: tabular-nums lining-nums; }
:focus-visible { outline: 2px solid var(--fl-accent); outline-offset: 2px; border-radius: 4px; }
.load { padding: 90px 20px; text-align: center; color: var(--fl-muted); font-size: 13.5px; }

/* ---- header ---- */
.hdr { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }
.hdr-l { display: flex; gap: 14px; min-width: 0; align-items: flex-start; flex: 1; }
.glyph {
  width: 40px; height: 40px; flex: none; display: grid; place-items: center;
  border-radius: 12px; color: var(--ax);
  background: color-mix(in srgb, var(--fl-accent) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--fl-accent) 22%, transparent);
}
.glyph svg { width: 22px; height: 22px; }
.title { margin: 1px 0 0; font-size: 24px; line-height: 1.12; font-weight: 750; letter-spacing: -0.02em; color: var(--fl-text); }
.brief { margin-top: 7px; font-size: 13px; line-height: 1.55; color: var(--fl-muted); }
.brief b { color: var(--fl-text); font-weight: 650; font-variant-numeric: tabular-nums; }
.brief .dot { margin: 0 7px; color: var(--fl-faint); }
.hdr-r { display: flex; gap: 10px; flex: none; align-items: center; padding-top: 2px; }

.btn {
  appearance: none; cursor: pointer; border-radius: 11px; padding: 10px 16px;
  font-weight: 650; font-size: 13.5px; font-family: inherit;
  display: inline-flex; align-items: center; gap: 8px; white-space: nowrap;
  transition: filter .15s ease, transform .06s ease, border-color .15s ease;
}
.btn:active { transform: translateY(1px); }
.btn svg { width: 16px; height: 16px; }
.btn-primary {
  border: 0; background: var(--fl-accent); color: var(--fl-accent-contrast);
  box-shadow: 0 8px 20px -10px color-mix(in srgb, var(--fl-accent) 70%, transparent);
}
.btn-primary:hover { filter: brightness(1.07); }
.btn-ghost { background: transparent; border: 1px solid var(--fl-border); color: var(--fl-text); }
.btn-ghost:hover { border-color: color-mix(in srgb, var(--fl-accent) 45%, transparent); }

/* ---- KPI lede ---- */
.kpis { display: grid; grid-template-columns: 1.6fr 1fr 1fr 1fr; gap: 14px; }
.kpi {
  background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 16px;
  padding: 16px 18px; box-shadow: var(--fl-shadow); min-width: 0;
  display: flex; flex-direction: column;
}
.kpi:not(.kpi-hero) { justify-content: center; }
.kpi-label { font-size: 11px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--fl-muted); }
.kpi-val { margin-top: 7px; font-size: 25px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.05; color: var(--fl-text); font-variant-numeric: tabular-nums; }
.kpi-hero .kpi-val { font-size: 33px; }
.kpi-sub { margin-top: 5px; font-size: 12px; color: var(--fl-faint); }
.kpi-sub b { color: var(--fl-muted); font-weight: 650; font-variant-numeric: tabular-nums; }
.kpi-spark { margin-top: auto; padding-top: 10px; }
.kpi-spark svg { display: block; width: 100%; height: 42px; }

/* ---- section labels ---- */
.sec {
  display: flex; align-items: center; gap: 10px; margin: 24px 0 12px;
  font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--fl-muted);
}
.sec::after { content: ""; flex: 1; height: 1px; background: var(--fl-border); }

/* ---- grid + panels ---- */
.grid { display: grid; gap: 14px; align-items: start; }
.g21 { grid-template-columns: 2fr 1fr; }
.g11 { grid-template-columns: 1fr 1fr; }
.col { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.panel {
  background: var(--fl-surface); border: 1px solid var(--fl-border); border-radius: 16px;
  box-shadow: var(--fl-shadow); padding: 16px 18px; min-width: 0;
}
.panel-h { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.panel-t { font-size: 13.5px; font-weight: 700; color: var(--fl-text); }
.panel-link { background: none; border: 0; padding: 0; cursor: pointer; font-family: inherit; font-size: 12px; font-weight: 650; color: var(--ax); }
.panel-link:hover { text-decoration: underline; }

/* ---- rows ---- */
.rows { display: flex; flex-direction: column; }
.row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid var(--fl-border); }
.row:first-child { border-top: 0; padding-top: 2px; }
.rows .row:last-child { padding-bottom: 2px; }
.row-main { min-width: 0; flex: 1; }
.row-title { font-size: 13.5px; font-weight: 600; color: var(--fl-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-sub { margin-top: 2px; font-size: 12px; color: var(--fl-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-r { text-align: right; flex: none; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }

.pill { display: inline-flex; align-items: center; font-size: 10.5px; font-weight: 700; padding: 3px 9px; border-radius: 999px; white-space: nowrap; }
.chip { font-size: 11.5px; font-weight: 650; color: var(--fl-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* ---- breakdown bars ---- */
.bar-row { display: grid; grid-template-columns: minmax(90px, 150px) 1fr 46px; align-items: center; gap: 10px; padding: 5px 0; }
.bar-name { font-size: 12.5px; color: var(--fl-muted); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.bar-track { height: 8px; border-radius: 5px; background: var(--fl-track); overflow: hidden; }
.bar-fill { height: 100%; width: 0; border-radius: 5px; background: var(--fl-accent); transition: width .9s cubic-bezier(.22, 1, .36, 1); }
.bar-val { font-size: 12.5px; font-weight: 700; color: var(--fl-text); text-align: right; font-variant-numeric: tabular-nums; }

/* ---- per-employee progress (the centerpiece) ---- */
.emp { display: flex; flex-direction: column; }
.emp-row { padding: 10px 0 12px; border-top: 1px solid var(--fl-border); }
.emp-row:first-child { border-top: 0; padding-top: 2px; }
.emp-top { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.avatar {
  width: 30px; height: 30px; flex: none; border-radius: 9px; display: grid; place-items: center;
  font-size: 11.5px; font-weight: 700; color: var(--ax);
  background: color-mix(in srgb, var(--fl-accent) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--fl-accent) 20%, transparent);
}
.emp-who { min-width: 0; flex: 1; }
.emp-name { font-size: 13.5px; font-weight: 600; color: var(--fl-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.emp-dept { margin-top: 1px; font-size: 11.5px; color: var(--fl-faint); }
.emp-r { flex: none; display: flex; align-items: center; gap: 8px; }
.track { height: 8px; border-radius: 5px; background: var(--fl-track); overflow: hidden; }
.track > i { display: block; height: 100%; width: 0; border-radius: 5px; background: var(--fl-accent); transition: width .9s cubic-bezier(.22, 1, .36, 1); }
.track.full > i { background: var(--fl-good); }

/* ---- completion ring ---- */
.ring-row { display: flex; align-items: center; gap: 16px; }
.ring {
  --pct: 0; width: 104px; height: 104px; flex: none; border-radius: 50%;
  background: conic-gradient(var(--fl-accent) calc(var(--pct) * 1%), var(--fl-track) 0);
  display: grid; place-items: center; position: relative;
}
.ring::after { content: ""; position: absolute; inset: 10px; border-radius: 50%; background: var(--fl-surface); border: 1px solid var(--fl-border); }
.ring-lbl { position: relative; text-align: center; z-index: 1; }
.ring-lbl b { font-size: 23px; font-weight: 800; letter-spacing: -0.02em; color: var(--fl-text); font-variant-numeric: tabular-nums; }
.ring-lbl span { display: block; margin-top: 2px; font-size: 10px; font-weight: 650; color: var(--fl-muted); letter-spacing: .07em; text-transform: uppercase; }
.ring-meta { color: var(--fl-muted); font-size: 12.5px; line-height: 1.65; min-width: 0; }
.ring-meta b { color: var(--fl-text); font-weight: 650; font-variant-numeric: tabular-nums; }

/* ---- policy compliance stack ---- */
.comp-stack { height: 10px; border-radius: 999px; overflow: hidden; display: flex; background: var(--fl-track); }
.comp-stack > i { display: block; height: 100%; width: 0; transition: width .9s cubic-bezier(.22, 1, .36, 1); }
.comp-stack > .ack { background: var(--fl-good); }
.comp-stack > .pend { background: color-mix(in srgb, var(--fl-warn) 45%, transparent); }
.comp-legend { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 12px; font-size: 12px; color: var(--fl-muted); }
.comp-legend b { color: var(--fl-text); font-weight: 650; font-variant-numeric: tabular-nums; }
.lg-dot { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 6px; vertical-align: middle; }
.lg-dot.g { background: var(--fl-good); }
.lg-dot.y { background: var(--fl-warn); }

/* ---- recent activity ---- */
.f-ic { width: 30px; height: 30px; flex: none; border-radius: 9px; display: grid; place-items: center; }
.f-ic svg { width: 15px; height: 15px; }
.f-ic.e { color: var(--ax); background: color-mix(in srgb, var(--fl-accent) 13%, transparent); }
.f-ic.t { color: var(--fl-good); background: color-mix(in srgb, var(--fl-good) 14%, transparent); }
.f-ic.p { color: var(--fl-warn); background: color-mix(in srgb, var(--fl-warn) 15%, transparent); }

/* ---- quick actions ---- */
.acts { display: flex; flex-wrap: wrap; gap: 10px; }
.act {
  display: inline-flex; align-items: center; gap: 9px;
  background: var(--fl-surface); border: 1px solid var(--fl-border); color: var(--fl-text);
  border-radius: 12px; padding: 10px 14px; cursor: pointer; font-family: inherit;
  font-weight: 600; font-size: 13px;
  transition: border-color .15s ease, transform .06s ease, box-shadow .15s ease;
}
.act:hover { border-color: color-mix(in srgb, var(--fl-accent) 50%, transparent); box-shadow: var(--fl-shadow); }
.act:active { transform: translateY(1px); }
.act svg { width: 16px; height: 16px; color: var(--ax); }

/* ---- empty + error states ---- */
.empty { padding: 22px 12px; text-align: center; color: var(--fl-muted); font-size: 13px; line-height: 1.5; }
.empty svg { width: 22px; height: 22px; color: var(--fl-faint); display: block; margin: 0 auto 8px; }
.empty .acts { justify-content: center; margin-top: 14px; }
.link-btn { background: none; border: 0; padding: 4px 0; color: var(--ax); cursor: pointer; font-family: inherit; font-weight: 650; font-size: 13px; }
.link-btn:hover { text-decoration: underline; }

/* ---- reveal motion ---- */
.reveal { opacity: 0; transform: translateY(10px); animation: flin .55s cubic-bezier(.22, 1, .36, 1) forwards; }
@keyframes flin { to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .reveal { animation: none; opacity: 1; transform: none; }
  .bar-fill, .track > i, .comp-stack > i { transition: none; }
}

@media (max-width: 960px) {
  .kpis { grid-template-columns: 1fr 1fr; }
  .g21, .g11 { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .wrap { padding: 20px 14px 48px; }
  .kpi-hero { grid-column: 1 / -1; }
  .kpis .kpi:last-child:nth-child(even) { grid-column: 1 / -1; }
  .hdr-r { width: 100%; flex-wrap: wrap; }
  .hdr-r .btn { flex: 1; justify-content: center; }
  .bar-row { grid-template-columns: minmax(76px, 110px) 1fr 40px; }
  .title { font-size: 21px; }
}

