// ---- small render helpers (kit grammar) ----
function fmtInt(n: number): string {
  return n.toLocaleString();
}

function fmtDay(when: string): string {
  const d = new Date(when);
  return isNaN(d.getTime()) ? "" : d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

type PillKind = "good" | "warn" | "bad" | "accent" | "neutral";

function pill(text: string, kind: PillKind): string {
  const c =
    kind === "good" ? "var(--fl-good)" :
    kind === "warn" ? "var(--fl-warn)" :
    kind === "bad" ? "var(--fl-bad)" :
    kind === "accent" ? "var(--ax)" : "var(--fl-muted)";
  const bg = kind === "neutral" ? "var(--fl-track)" : "color-mix(in srgb, " + c + " 15%, transparent)";
  return '<span class="pill" style="color:' + c + ";background:" + bg + '">' + esc(text) + "</span>";
}

function spark(vals: number[]): string {
  const w = 220;
  const hh = 42;
  if (vals.length < 2) return "";
  let mx = 0;
  let mn = Infinity;
  for (const v of vals) {
    if (v > mx) mx = v;
    if (v < mn) mn = v;
  }
  if (mx === 0) return "";
  if (mn === mx) mn = 0;
  const rng = mx - mn || 1;
  const pts: string[] = [];
  for (let j = 0; j < vals.length; j++) {
    const x = 2 + (j / (vals.length - 1)) * (w - 4);
    const y = hh - 5 - ((vals[j] - mn) / rng) * (hh - 12);
    pts.push(x.toFixed(1) + "," + y.toFixed(1));
  }
  const line = pts.join(" ");
  return (
    '<svg viewBox="0 0 ' + w + " " + hh + '" preserveAspectRatio="none" aria-hidden="true">' +
    '<polygon points="2,' + (hh - 2) + " " + line + " " + (w - 2) + "," + (hh - 2) + '"' +
    ' fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/>' +
    '<polyline points="' + line + '" fill="none" stroke="var(--fl-accent)" stroke-width="2"' +
    ' stroke-linecap="round" stroke-linejoin="round"/></svg>'
  );
}

function kpi(label: string, valHtml: string, subHtml: string, opts?: { hero?: boolean; spark?: string }): string {
  return (
    '<div class="kpi' + (opts && opts.hero ? " kpi-hero" : "") + '">' +
    '<div class="kpi-label">' + esc(label) + "</div>" +
    '<div class="kpi-val">' + valHtml + "</div>" +
    (subHtml ? '<div class="kpi-sub">' + subHtml + "</div>" : "") +
    (opts && opts.spark ? '<div class="kpi-spark">' + opts.spark + "</div>" : "") +
    "</div>"
  );
}

function sec(label: string): string {
  return '<div class="sec">' + esc(label) + "</div>";
}

function panel(title: string, body: string, nav?: string, navLabel?: string): string {
  return (
    '<div class="panel"><div class="panel-h"><div class="panel-t">' + esc(title) + "</div>" +
    (nav ? '<button class="panel-link" type="button" data-nav="' + esc(nav) + '">' + esc(navLabel || "View all") + "</button>" : "") +
    "</div>" + body + "</div>"
  );
}

function emptyBlock(icon: string, msg: string, nav: string | null, cta: string): string {
  return (
    '<div class="empty">' + icon + esc(msg) +
    (nav ? '<div><button class="link-btn" type="button" data-nav="' + esc(nav) + '">' + esc(cta) + "</button></div>" : "") +
    "</div>"
  );
}

// ---- header: glyph tile + title + briefing + CTAs ----
function header(d: Dashboard): string {
  const clauses: string[] = [];
  clauses.push("<b>" + fmtInt(d.activeOnboarding) + "</b> onboarding");
  clauses.push(
    d.overdue > 0
      ? "<b>" + fmtInt(d.overdue) + "</b> " + (d.overdue === 1 ? "task" : "tasks") + " overdue"
      : "<b>" + fmtInt(d.outstanding) + "</b> " + (d.outstanding === 1 ? "task" : "tasks") + " open",
  );
  clauses.push(
    d.pending > 0
      ? "<b>" + fmtInt(d.pending) + "</b> " + (d.pending === 1 ? "policy" : "policies") + " pending"
      : "<b>" + fmtInt(d.acknowledged) + "</b> " + (d.acknowledged === 1 ? "policy" : "policies") + " acknowledged",
  );
  const brief = clauses.join('<span class="dot">·</span>');
  let ctas = "";
  if (d.employeesFormId) {
    ctas += '<button class="btn btn-primary" type="button" data-nav="' + esc(d.employeesFormId) + '">' + I.plus + "<span>Add employee</span></button>";
  }
  ctas += '<button class="btn btn-ghost" type="button" data-refresh="1">' + I.refresh + "<span>Refresh</span></button>";
  return (
    '<div class="hdr"><div class="hdr-l"><div class="glyph">' + I.userCheck + "</div>" +
    '<div style="min-width:0"><h1 class="title">People Onboarding &amp; Compliance</h1>' +
    '<div class="brief">' + brief + "</div></div></div>" +
    '<div class="hdr-r">' + ctas + "</div></div>"
  );
}

// ---- KPI lede: hero completion + three compact tiles ----
function kpiRow(d: Dashboard): string {
  return (
    '<div class="kpis">' +
    kpi(
      "Onboarding complete",
      d.completionPct + "%",
      "<b>" + fmtInt(d.doneTasks) + "</b> of <b>" + fmtInt(d.totalTasks) + "</b> tasks done",
      { hero: true, spark: spark(d.weeklyTasks) },
    ) +
    kpi("Employees", '<span data-count="' + d.totalEmployees + '">' + fmtInt(d.totalEmployees) + "</span>", "on the roster") +
    kpi(
      "Overdue tasks",
      '<span data-count="' + d.overdue + '">' + fmtInt(d.overdue) + "</span>",
      d.overdue > 0 ? "past their due date" : "nothing past due",
    ) +
    kpi("Policy compliance", d.compliancePct + "%", "<b>" + fmtInt(d.acknowledged) + "</b> of <b>" + fmtInt(d.totalPolicies) + "</b> acknowledged") +
    "</div>"
  );
}

// ---- centerpiece: per-employee progress ----
function progressPanel(d: Dashboard, rows: EmployeeProgress[]): string {
  let body: string;
  if (rows.length === 0) {
    body = emptyBlock(I.users, "No employees yet. Add your first hire to start tracking onboarding.", d.employeesFormId, "+ Add employee");
  } else {
    body =
      '<div class="emp">' +
      rows
        .slice(0, 12)
        .map((e) => {
          const complete = e.total > 0 && e.done === e.total;
          const right = complete
            ? pill("Done", "good")
            : '<span class="chip">' + (e.total > 0 ? e.done + "/" + e.total + " tasks" : "no tasks yet") + "</span>";
          return (
            '<div class="emp-row"><div class="emp-top">' +
            '<div class="avatar">' + esc(initials(e.name)) + "</div>" +
            '<div class="emp-who"><div class="emp-name">' + esc(e.name) + "</div>" +
            '<div class="emp-dept">' + esc(e.dept) + "</div></div>" +
            '<div class="emp-r">' + right + "</div></div>" +
            '<div class="track' + (complete ? " full" : "") + '"><i data-pct="' + e.pct + '"></i></div>' +
            "</div>"
          );
        })
        .join("") +
      "</div>";
  }
  const nav = d.employeesFormId ? "form/" + d.employeesFormId + "/responses" : undefined;
  return panel("Per-employee progress", body, nav);
}

// ---- completion ring ----
function completionPanel(d: Dashboard): string {
  const body =
    '<div class="ring-row">' +
    '<div class="ring" style="--pct:' + d.completionPct + '">' +
    '<div class="ring-lbl"><b>' + d.completionPct + "%</b><span>complete</span></div></div>" +
    '<div class="ring-meta">' +
    "<b>" + fmtInt(d.doneTasks) + "</b> of <b>" + fmtInt(d.totalTasks) + "</b> tasks done<br>" +
    "<b>" + fmtInt(d.outstanding) + "</b> still outstanding<br>" +
    "across <b>" + fmtInt(d.totalEmployees) + "</b> employees" +
    "</div></div>";
  return panel("Onboarding completion", body);
}

// ---- outstanding by category (kit breakdown bars) ----
function categoryPanel(d: Dashboard, cats: CategoryStat[]): string {
  const max = Math.max(1, ...cats.map((c) => c.count));
  const total = cats.reduce((s, c) => s + c.count, 0);
  let body: string;
  if (total === 0) {
    body = emptyBlock(I.check, "No outstanding tasks. Everything is on track.", d.tasksFormId, "+ New task");
  } else {
    body = cats
      .filter((c) => c.count > 0)
      .map((c) => {
        const w = Math.max(3, Math.round((c.count / max) * 100));
        return (
          '<div class="bar-row"><span class="bar-name" title="' + esc(c.label) + '">' + esc(c.label) + "</span>" +
          '<div class="bar-track"><div class="bar-fill" data-pct="' + w + '"></div></div>' +
          '<span class="bar-val">' + fmtInt(c.count) + "</span></div>"
        );
      })
      .join("");
  }
  const nav = d.tasksFormId ? "form/" + d.tasksFormId + "/responses" : undefined;
  return panel("Outstanding by category", body, nav);
}

// ---- policy compliance stack ----
function compliancePanel(d: Dashboard): string {
  let body: string;
  if (d.totalPolicies === 0) {
    body = emptyBlock(I.shield, "No policy acknowledgements recorded yet.", d.policyFormId, "+ Acknowledge policy");
  } else {
    const ackW = Math.round((d.acknowledged / d.totalPolicies) * 100);
    body =
      '<div class="comp-stack"><i class="ack" data-pct="' + ackW + '"></i><i class="pend" data-pct="' + (100 - ackW) + '"></i></div>' +
      '<div class="comp-legend">' +
      '<span><span class="lg-dot g"></span><b>' + fmtInt(d.acknowledged) + "</b>&nbsp;acknowledged</span>" +
      '<span><span class="lg-dot y"></span><b>' + fmtInt(d.pending) + "</b>&nbsp;pending</span>" +
      '<span style="margin-left:auto">' + pill(d.compliancePct + "% compliant", d.compliancePct >= 100 ? "good" : d.compliancePct >= 50 ? "accent" : "warn") + "</span>" +
      "</div>";
  }
  const nav = d.policyFormId ? "form/" + d.policyFormId + "/responses" : undefined;
  return panel("Policy compliance", body, nav);
}

// ---- recent activity ----
function feedPanel(d: Dashboard, items: RecentItem[]): string {
  let body: string;
  if (items.length === 0) {
    body = emptyBlock(I.doc, "Activity will appear here as your team onboards.", d.employeesFormId, "+ Add employee");
  } else {
    const icon: Record<string, string> = { employee: I.user, task: I.check, policy: I.shield };
    const cls: Record<string, string> = { employee: "e", task: "t", policy: "p" };
    body =
      '<div class="rows">' +
      items
        .map((it) => {
          const when = fmtDay(it.when);
          return (
            '<div class="row"><div class="f-ic ' + cls[it.kind] + '">' + icon[it.kind] + "</div>" +
            '<div class="row-main"><div class="row-title">' + esc(it.text) + "</div></div>" +
            (when ? '<div class="row-r"><span class="chip">' + esc(when) + "</span></div>" : "") +
            "</div>"
          );
        })
        .join("") +
      "</div>";
  }
  return panel("Recent activity", body);
}

// ---- quick actions ----
function actionsRow(d: Dashboard): string {
  const items: Array<{ nav: string | null; label: string; icon: string }> = [
    { nav: d.tasksFormId, label: "New task", icon: I.plus },
    { nav: d.policyFormId, label: "Acknowledge policy", icon: I.shield },
    { nav: d.employeesFormId ? "form/" + d.employeesFormId + "/responses" : null, label: "View employees", icon: I.users },
    { nav: "records", label: "All records", icon: I.box },
    { nav: "reports", label: "Reports", icon: I.chart },
  ];
  let out = '<div class="acts">';
  for (const it of items) {
    if (!it.nav) continue;
    out += '<button class="act" type="button" data-nav="' + esc(it.nav) + '">' + it.icon + "<span>" + esc(it.label) + "</span></button>";
  }
  return out + "</div>";
