// ---- first-run empty state (warm, directive, no emoji) ----
function renderEmpty(d: Dashboard): string {
  const q = (formId: string | null, cls: string, label: string): string =>
    formId
      ? '<button class="btn ' + cls + '" type="button" data-nav="' + esc(formId) + '">' + I.plus + "<span>" + esc(label) + "</span></button>"
      : "";
  return (
    header(d) +
    '<div class="panel"><div class="empty">' + I.users +
    "Add an employee, assign their onboarding tasks, and capture policy acknowledgements — " +
    "your live completion and compliance metrics will build automatically." +
    '<div class="acts">' +
    q(d.employeesFormId, "btn-primary", "Add employee") +
    q(d.tasksFormId, "btn-ghost", "New onboarding task") +
    q(d.policyFormId, "btn-ghost", "Acknowledge a policy") +
    "</div></div></div>"
  );
}

// ---- motion: staggered reveal, bar draw, count-up (all reduced-motion aware) ----
function countUp(el: HTMLElement): void {
  const target = parseFloat(el.getAttribute("data-count") || "");
  if (isNaN(target) || target <= 0) return;
  let t0: number | null = null;
  const dur = 700;
  const step = (ts: number): void => {
    if (t0 === null) t0 = ts;
    const p = Math.min(1, (ts - t0) / dur);
    const e = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(target * e).toLocaleString();
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function animate(): void {
  const kids = root.querySelectorAll(".wrap > *");
  for (let k = 0; k < kids.length; k++) {
    kids[k].classList.add("reveal");
    (kids[k] as HTMLElement).style.animationDelay = Math.min(k, 8) * 60 + "ms";
  }
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const fills = root.querySelectorAll<HTMLElement>("[data-pct]");
      for (let j = 0; j < fills.length; j++) {
        fills[j].style.width = (fills[j].getAttribute("data-pct") || 0) + "%";
      }
    });
  });
  if (!reducedMotion) {
    const counters = root.querySelectorAll<HTMLElement>("[data-count]");
    for (let m = 0; m < counters.length; m++) countUp(counters[m]);
  }
}

function render(d: Dashboard): void {
  const hasData = d.totalEmployees > 0 || d.totalTasks > 0 || d.totalPolicies > 0;
  if (!hasData) {
    root.innerHTML = '<div class="wrap">' + renderEmpty(d) + "</div>";
    animate();
    return;
  }
  root.innerHTML =
    '<div class="wrap">' +
    header(d) +
    kpiRow(d) +
    sec("Onboarding pipeline") +
    '<div class="grid g21">' +
    progressPanel(d, d.progress) +
    '<div class="col">' + completionPanel(d) + categoryPanel(d, d.categories) + "</div>" +
    "</div>" +
    sec("Compliance & activity") +
    '<div class="grid g11">' + compliancePanel(d) + feedPanel(d, d.recent) + "</div>" +
    sec("Quick actions") +
    actionsRow(d) +
    "</div>";
  animate();
}

async function refresh(): Promise<void> {
  try {
    const d = await loadDashboard();
    render(d);
  } catch (err) {
    root.innerHTML =
      '<div class="wrap"><div class="panel"><div class="empty">' + I.alert +
      "Could not load the dashboard. Please try refreshing in a moment." +
      '<div><button class="link-btn" type="button" data-refresh="1">Try again</button></div>' +
      "</div></div></div>";
    FL.toast.error("Failed to load onboarding data");
  }
}

// One delegated click handler survives every re-render of root.innerHTML.
root.addEventListener("click", (ev) => {
  const t = ev.target as HTMLElement;
  const nav = t.closest("[data-nav]") as HTMLElement | null;
  if (nav) {
    const fid = nav.getAttribute("data-nav");
    if (fid) FL.navigate(fid);
    return;
  }
  if (t.closest("[data-refresh]")) {
    void refresh();
  }
});

void refresh();
